// src/consent/ask.ts
import { createHash } from "node:crypto";
var confirmation = object({
  confirm: boolean2().describe("Tick to confirm; leave it to refuse.")
});
function answerOf(ctx, key) {
  const view = inputResponse(ctx.inputResponses, key);
  if (view.kind === "missing") return "unasked";
  if (view.kind !== "elicit" || view.action !== "accept") return "no";
  const content2 = confirmation.safeParse(view.content);
  return content2.success && content2.data.confirm ? "yes" : "no";
}
var QuestionForUser = class extends Error {
  name = "QuestionForUser";
  requests;
  constructor(key, message2) {
    super(key);
    this.requests = {
      [key]: inputRequired.elicit({ message: message2, requestedSchema: confirmation })
    };
  }
};
function askUser(ctx, key, message2, refusal2) {
  if (ctx.canAsk !== true) throw refusal2;
  throw new QuestionForUser(key, message2);
}
function declaresForm(capabilities) {
  if (typeof capabilities !== "object" || capabilities === null) return false;
  const elicitation = capabilities.elicitation;
  if (typeof elicitation !== "object" || elicitation === null) return false;
  const modes = Object.keys(elicitation);
  return modes.length === 0 || modes.includes("form");
}
function questionResult(question) {
  return inputRequired({ inputRequests: question.requests });
}
function questionKey(id3, message2) {
  const digest2 = createHash("sha256").update(message2).digest("hex").slice(0, 16);
  return `confirm:${createHash("sha256").update(id3).digest("hex").slice(0, 16)}:${digest2}`;
}
function confirmOnce(ctx, id3, message2, refusal2) {
  const key = questionKey(id3, message2);
  const answer = answerOf(ctx, key);
  if (answer === "yes") return;
  if (answer === "no") throw refusal2;
  askUser(ctx, key, message2, refusal2);
}

